// Lo único que se interpola en la consulta es el ID, así que acá se exige que
// sea solo dígitos. Cualquier otra cosa corta la corrida sin tocar SQL Server.
const cuerpo = $input.first().json.body ?? {};
const id = String(cuerpo.id ?? '').trim();
if (!/^\d{5,12}$/.test(id)) {
  throw new Error('ID de viaje inválido: tiene que ser un número de 5 a 12 dígitos.');
}
return [{ json: { id } }];

// Una fila por movimiento, con la ficha del viaje repetida en cada una.
// Se devuelve un solo objeto: la ficha completa y su historial cronológico.
const filas = $input.all().map((item) => item.json);
const primera = filas[0] ?? {};

if (!primera.IdViaje) {
  return [{ json: { encontrado: false, id: String(primera.IdConsultado ?? '') } }];
}

const visitado = (valor) => valor === true || valor === 1 || valor === '1';
const texto = (valor) => valor === null || valor === undefined || String(valor).trim() === '' ? null : String(valor).trim();
const numero = (valor) => valor === null || valor === undefined || valor === '' || !Number.isFinite(Number(valor)) ? null : Number(valor);

return [{
  json: {
    encontrado: true,
    id: String(primera.IdViaje),
    viaje: {
      tracking_id: texto(primera.TrackingId) ?? String(primera.IdViaje),
      referencia_auxiliar: texto(primera.ReferenciaAuxiliar),
      id_usuario: numero(primera.IdUsuario),
      id_reserva: numero(primera.IdReserva),
      id_ruta: numero(primera.IdRuta),
      id_estado: numero(primera.IdEstado),
      orden: numero(primera.Orden),
      estado_actual: texto(primera.EstadoActual),
      tienda: texto(primera.Tienda),
      id_modalidad: numero(primera.IdModalidad),
      id_localidad: numero(primera.IdLocalidad),
      poligono: texto(primera.Poligono),
      direccion: texto(primera.Direccion),
      telefono: texto(primera.Telefono),
      ciudad: texto(primera.Ciudad),
      barrio: texto(primera.Barrio),
      codigo_postal: texto(primera.CodigoPostal),
      observacion_direccion: texto(primera.ObservacionDireccion),
      observacion_destino: texto(primera.ObservacionDestino),
      nombre_recibe: texto(primera.NombreRecibe),
      comentario_motoboy: texto(primera.ComentarioMotoboy),
      comentario_estado: texto(primera.ComentarioEstado),
      motivo_no_entregado: texto(primera.MotivoNoEntregado),
      motivo_no_devuelto: texto(primera.MotivoNoDevuelto),
      latitud_destino: numero(primera.LatitudDestino),
      longitud_destino: numero(primera.LongitudDestino),
      fecha_programado: texto(primera.FechaProgramado),
      fecha_programado_hasta: texto(primera.FechaProgramadoHasta),
      fecha_cambio_estado: texto(primera.FechaCambioEstado),
      visitas: numero(primera.Visitas),
      evidencia_foto: texto(primera.EvidenciaFoto),
      fecha_evidencia: texto(primera.FechaEvidencia),
    },
    historial: filas
      .filter((fila) => fila.Fecha)
      .map((fila) => ({
        fecha: fila.Fecha,
        estado: texto(fila.Estado),
        repartidor: texto(fila.Repartidor),
        visitado: visitado(fila.VisitadoMotoboy),
        responsable: texto(fila.Responsable),
        foto: texto(fila.Foto),
      })),
  },
}];
